// Lista fija de años a recorrer.
// Editar este array a mano si en el futuro se quieren cubrir más años.
const anios = [2025, 2026];

return anios.map(a => ({ json: { anio: a } }));

// Extrae TODOS los links de boletin del HTML del listado_ajax para
// el anio consultado, deduplicando (el HTML del DGE repite cada link
// 2 veces: en la miniatura y en el titulo).
//
// IMPORTANTE: la semana NO se parsea del nombre del archivo del PDF,
// porque el DGE es inconsistente ahi (a veces '202610' = anio+semana
// con 2 digitos, a veces '20269' = semana de 1 solo digito sin
// relleno de cero, y a veces falta el numero de semana por completo
// en el nombre, ej. 'boletin_2026_30_112436.pdf'). En vez de eso, se
// usa el <span class='periodoVal'>N</span> que el DGE SI pone siempre
// de forma confiable junto a cada link, dentro del mismo bloque <tr>.
//
// La fecha de publicacion tampoco se parsea del nombre del archivo:
// se toma del texto 'fecha publicacion: DD-MM-AAAA' que tambien
// aparece siempre en el HTML, junto a cada boletin.

const html = $input.first().json.data || $input.first().json.body || $input.first().json;
const anioConsultado = $('Split In Batches (anios)').item.json.anio;

// Cada fila <tr> trae: el link (repetido 2 veces), el periodoVal (semana)
// y la fecha de publicacion. Se captura el bloque <tr>...</tr> completo
// y se extraen esos 3 datos de adentro.
const filaRegex = /<tr>([\s\S]*?)<\/tr>/g;
const filas = [...html.matchAll(filaRegex)];

if (filas.length === 0) {
  return [];
}

const vistos = new Set();
const items = [];

for (const fila of filas) {
  const bloque = fila[1];

  const urlMatch = bloque.match(/href='(https:\/\/epipublic\.dge\.gob\.pe\/uploads\/boletin\/boletin_[^']+\.pdf)'/);
  const semanaMatch = bloque.match(/periodoVal'>(\d{1,2})<\/span>/);
  const fechaMatch = bloque.match(/fecha publicacion:\s*(\d{2})-(\d{2})-(\d{4})/);

  if (!urlMatch || !semanaMatch) continue; // fila sin link o sin semana valida, se descarta

  const urlBoletin = urlMatch[1];
  if (vistos.has(urlBoletin)) continue; // deduplicar (el link aparece 2 veces por fila)
  vistos.add(urlBoletin);

  const semana = Number(semanaMatch[1]);

  let fechaPublicacion = null;
  if (fechaMatch) {
    const [, dd, mm, aaaa] = fechaMatch;
    fechaPublicacion = `${aaaa}-${mm}-${dd}`; // formato ISO, ej. 2026-04-12
  }

  items.push({
    json: {
      url_boletin: urlBoletin,
      anio: anioConsultado,          // anio real, tomado del parametro que se mando al DGE
      semana_epidemiologica: semana, // tomado del periodoVal del HTML, no del nombre del archivo
      fecha_publicacion: fechaPublicacion
    }
  });
}

return items;

// Descarta del listado nuevo cualquier boletin cuya combinacion
// anio + semana_epidemiologica YA exista en boletines_descubiertos.

const clave = (anio, semana) => `${anio}-${semana}`;

const nuevos = $('Extraer links + fecha/semana (dedup)').all().map(i => i.json);

const filasExistentes = $('Get row(s) boletines_descubiertos').all();

const yaExistentes = new Set(
  filasExistentes.map(i => clave(i.json.anio, i.json.semana_epidemiologica))
);

console.log('Filas ya existentes leidas:', filasExistentes.length);
console.log('Links nuevos encontrados en el listado:', nuevos.length);
console.log('Claves existentes (muestra 5):', JSON.stringify([...yaExistentes].slice(0, 5)));
console.log('Claves nuevas a comparar (muestra 5):', JSON.stringify(nuevos.slice(0, 5).map(item => clave(item.anio, item.semana_epidemiologica))));

const pendientesNuevos = nuevos
  .filter(item => !yaExistentes.has(clave(item.anio, item.semana_epidemiologica)))
  .map(item => ({ ...item, resumen: '', procesado: false, _sinPendientes: false }));

console.log('Pendientes realmente nuevos a insertar:', pendientesNuevos.length);

if (pendientesNuevos.length === 0) {
  return [{ json: { _sinPendientes: true } }];
}

return pendientesNuevos.map(item => ({ json: item }));

