INSERT INTO boletin_descubierto (
  anio, semana_epidemiologica, url_boletin, fecha_publicacion
) VALUES (
  {{ $json.anio }},
  {{ $json.semana_epidemiologica }},
  '{{ $json.url_boletin }}',
  {{ $json.fecha_publicacion ? "'" + $json.fecha_publicacion + "'" : "NULL" }}
)
ON CONFLICT (anio, semana_epidemiologica) DO NOTHING;
